from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class PucchTestResults(SchemaObject):
    time = SchemaField(name="time", not_null=True)
    detected_counter = SchemaField(name="detectedCounter", not_null=True)
    missed_counter = SchemaField(name="missedCounter", not_null=True)
    false_counter = SchemaField(name="falseCounter", not_null=True)
    idle_period_counter = SchemaField(name="idlePeriodCounter", not_null=True)

    def __init__(self, time=None, detected_counter=None, missed_counter=None, false_counter=None,
                 idle_period_counter=None):
        self.time = time
        self.detected_counter = detected_counter
        self.missed_counter = missed_counter
        self.false_counter = false_counter
        self.idle_period_counter = idle_period_counter


class PucchTestParams(SchemaObject):
    beam_pattern_id = SchemaField(name="beamPatternIdArray", not_null=True)
    reporting_time_interval = SchemaField(name="reportingTimeInterval", not_null=True)
    ru_mode = SchemaField(name="ruMode", not_null=True)
    phys_cell_id = SchemaField(name="physCellId", not_null=True)
    nrarfcn = SchemaField(name="nrarfcn", optional=True)
    nrarfcn_ul = SchemaField(name="nrarfcnUl", optional=True)
    nrarfcn_dl = SchemaField(name="nrarfcnDl", optional=True)
    expectation_slot = SchemaField(name="expectationSlot", not_null=True)
    receiving_slot = SchemaField(name="receivingSlot", not_null=True)
    prb_offset = SchemaField(name="prbOffset", not_null=True)
    pucch_format = SchemaField(name="pucchFormat", not_null=True)
    format3_additional_dmrs = SchemaField(name="format3AdditionalDmrs", not_null=True)
    largest_prb_index = SchemaField(name="largestPrbIndex", not_null=True)
    num_payload_bit = SchemaField(name="numPayloadBit", not_null=True)
    num_pucch_symbol = SchemaField(name="numPucchSymbol", not_null=True)
    pucch_payload_content = SchemaField(name="pucchPayloadContent", not_null=True)

    def __init__(self, beam_pattern_id=None, reporting_time_interval=None, ru_mode=None,
                 phys_cell_id=None, nrarfcn=None, expectation_slot=None, receiving_slot=None, prb_offset=None,
                 pucch_format=None, format3_additional_dmrs=None, largest_prb_index=None, num_payload_bit=None,
                 num_pucch_symbol=None, pucch_payload_content=None, nrarfcn_ul=None, nrarfcn_dl=None):
        self.beam_pattern_id = beam_pattern_id
        self.reporting_time_interval = reporting_time_interval
        self.ru_mode = ru_mode
        self.phys_cell_id = phys_cell_id
        self.expectation_slot = expectation_slot
        self.receiving_slot = receiving_slot
        self.prb_offset = prb_offset
        self.pucch_format = pucch_format
        self.format3_additional_dmrs = format3_additional_dmrs
        self.largest_prb_index = largest_prb_index
        self.num_payload_bit = num_payload_bit
        self.num_pucch_symbol = num_pucch_symbol
        self.pucch_payload_content = pucch_payload_content
        self.nrarfcn = nrarfcn
        self.nrarfcn_dl = nrarfcn_dl
        self.nrarfcn_ul = nrarfcn_ul


class GetPucchCPCONFIGV1(SchemaObject):
    pucch_test_params = SchemaField(name="pucchTestParams", klass=PucchTestParams)
    pucch_test_results = SchemaField(name="pucchTestResults", klass=PucchTestResults, many=True)

    def __init__(self, pucch_test_params=None, pucch_test_results=None):
        self.pucch_test_params = pucch_test_params
        self.pucch_test_results = pucch_test_results

        super(GetPucchCPCONFIGV1, self).__init__()
